function renderConsumerSummary() {
  const host = $("consumer-summary");
  host.replaceChildren();
  if(current?.status==="pending"){host.append(el2("p","Original code retained · checking owned source facts (up to40seconds)","label"));return;}
  if(selected2?.kind==="source-barcode-candidate"){for(const row of _OffMenuSourceBarcode.inventoryReadout(_OffMenuGuestFoundation.foundationReadout,selected2,current,"overview").slice(0,8))host.append(el2("p",row.label+": "+row.text,"label"));return;}
